-- =============================================================================
-- Auto Business — Calculated Dasha Prediction Engine (दशा फल v2) — migration 011
-- Data tables for the CALCULATED dasha engine (DashaPhalEngine): per-planet
-- text by house-from-Lagna (maha & antar), antar-from-mahalord by position,
-- and optional bhavesh overrides (empty here -> engine falls back to the
-- existing bhavesh_phal 144 table). Seeded from dasha_engine_data_template.xlsx.
-- Renumbered 004 -> 011 (004 already used). Self-contained + idempotent.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS dasha_lord_from_lagna (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  context ENUM('maha','antar') NOT NULL,
  planet VARCHAR(16) NOT NULL,
  house_from_lagna TINYINT NOT NULL,
  language VARCHAR(16) NOT NULL DEFAULT 'hi',
  positive_text TEXT NULL, negative_text TEXT NULL, remedy_text TEXT NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_dlfl (context, planet, house_from_lagna, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dasha_antar_from_maha (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  antar_planet VARCHAR(16) NOT NULL DEFAULT 'ANY',
  house_from_maha_lord TINYINT NOT NULL,
  language VARCHAR(16) NOT NULL DEFAULT 'hi',
  verdict VARCHAR(24) NULL,
  positive_text TEXT NULL, negative_text TEXT NULL, remedy_text TEXT NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_dafm (antar_planet, house_from_maha_lord, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dasha_bhavesh_phala (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  lord_of_house TINYINT NOT NULL, placed_in_house TINYINT NOT NULL,
  language VARCHAR(16) NOT NULL DEFAULT 'hi',
  positive_text TEXT NULL, negative_text TEXT NULL, remedy_text TEXT NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_dbp (lord_of_house, placed_in_house, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE positive_text=VALUES(positive_text),negative_text=VALUES(negative_text),remedy_text=VALUES(remedy_text);

ON DUPLICATE KEY UPDATE positive_text=VALUES(positive_text),negative_text=VALUES(negative_text),remedy_text=VALUES(remedy_text);

ON DUPLICATE KEY UPDATE verdict=VALUES(verdict),positive_text=VALUES(positive_text),negative_text=VALUES(negative_text),remedy_text=VALUES(remedy_text);

-- Bhavesh_Dasha sheet had no filled text rows -> engine falls back to the existing bhavesh_phal (144) table.

CREATE TABLE IF NOT EXISTS house_engine_config (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  cfg_key VARCHAR(64) NOT NULL, cfg_value VARCHAR(255) NULL, notes TEXT NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_cfg (cfg_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE cfg_value=VALUES(cfg_value),notes=VALUES(notes);

-- End of migration 011.
