INSERT INTO dasha_lord_from_lagna (context,planet,house_from_lagna,language,positive_text,negative_text,remedy_text) VALUES
('maha','Sun',1,'hi','सूर्य की महादशा में सूर्य लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',2,'hi','सूर्य की महादशा में सूर्य लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',3,'hi','सूर्य की महादशा में सूर्य लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',4,'hi','सूर्य की महादशा में सूर्य लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',5,'hi','सूर्य की महादशा में सूर्य लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',6,'hi','सूर्य की महादशा में सूर्य लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Sun',7,'hi','सूर्य की महादशा में सूर्य लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',8,'hi','सूर्य की महादशा में सूर्य लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Sun',9,'hi','सूर्य की महादशा में सूर्य लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',10,'hi','सूर्य की महादशा में सूर्य लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',11,'hi','सूर्य की महादशा में सूर्य लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('maha','Sun',12,'hi','सूर्य की महादशा में सूर्य लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Moon',1,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',2,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',3,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',4,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',5,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',6,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Moon',7,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',8,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Moon',9,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',10,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',11,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('maha','Moon',12,'hi','चन्द्रमा की महादशा में चन्द्रमा लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Mars',1,'hi','मंगल की महादशा में मंगल लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',2,'hi','मंगल की महादशा में मंगल लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',3,'hi','मंगल की महादशा में मंगल लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',4,'hi','मंगल की महादशा में मंगल लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',5,'hi','मंगल की महादशा में मंगल लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',6,'hi','मंगल की महादशा में मंगल लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Mars',7,'hi','मंगल की महादशा में मंगल लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',8,'hi','मंगल की महादशा में मंगल लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Mars',9,'hi','मंगल की महादशा में मंगल लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',10,'hi','मंगल की महादशा में मंगल लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',11,'hi','मंगल की महादशा में मंगल लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('maha','Mars',12,'hi','मंगल की महादशा में मंगल लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Rahu',1,'hi','राहु की महादशा में राहु लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',2,'hi','राहु की महादशा में राहु लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',3,'hi','राहु की महादशा में राहु लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',4,'hi','राहु की महादशा में राहु लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',5,'hi','राहु की महादशा में राहु लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',6,'hi','राहु की महादशा में राहु लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Rahu',7,'hi','राहु की महादशा में राहु लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',8,'hi','राहु की महादशा में राहु लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Rahu',9,'hi','राहु की महादशा में राहु लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',10,'hi','राहु की महादशा में राहु लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',11,'hi','राहु की महादशा में राहु लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('maha','Rahu',12,'hi','राहु की महादशा में राहु लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Jupiter',1,'hi','गुरु की महादशा में गुरु लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',2,'hi','गुरु की महादशा में गुरु लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',3,'hi','गुरु की महादशा में गुरु लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',4,'hi','गुरु की महादशा में गुरु लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',5,'hi','गुरु की महादशा में गुरु लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',6,'hi','गुरु की महादशा में गुरु लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Jupiter',7,'hi','गुरु की महादशा में गुरु लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',8,'hi','गुरु की महादशा में गुरु लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Jupiter',9,'hi','गुरु की महादशा में गुरु लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',10,'hi','गुरु की महादशा में गुरु लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',11,'hi','गुरु की महादशा में गुरु लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('maha','Jupiter',12,'hi','गुरु की महादशा में गुरु लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Saturn',1,'hi','शनि की महादशा में शनि लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',2,'hi','शनि की महादशा में शनि लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',3,'hi','शनि की महादशा में शनि लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',4,'hi','शनि की महादशा में शनि लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',5,'hi','शनि की महादशा में शनि लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',6,'hi','शनि की महादशा में शनि लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Saturn',7,'hi','शनि की महादशा में शनि लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',8,'hi','शनि की महादशा में शनि लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Saturn',9,'hi','शनि की महादशा में शनि लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',10,'hi','शनि की महादशा में शनि लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',11,'hi','शनि की महादशा में शनि लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('maha','Saturn',12,'hi','शनि की महादशा में शनि लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Mercury',1,'hi','बुध की महादशा में बुध लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',2,'hi','बुध की महादशा में बुध लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',3,'hi','बुध की महादशा में बुध लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',4,'hi','बुध की महादशा में बुध लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',5,'hi','बुध की महादशा में बुध लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',6,'hi','बुध की महादशा में बुध लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Mercury',7,'hi','बुध की महादशा में बुध लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',8,'hi','बुध की महादशा में बुध लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Mercury',9,'hi','बुध की महादशा में बुध लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',10,'hi','बुध की महादशा में बुध लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',11,'hi','बुध की महादशा में बुध लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('maha','Mercury',12,'hi','बुध की महादशा में बुध लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Ketu',1,'hi','केतु की महादशा में केतु लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',2,'hi','केतु की महादशा में केतु लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',3,'hi','केतु की महादशा में केतु लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',4,'hi','केतु की महादशा में केतु लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',5,'hi','केतु की महादशा में केतु लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',6,'hi','केतु की महादशा में केतु लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Ketu',7,'hi','केतु की महादशा में केतु लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',8,'hi','केतु की महादशा में केतु लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Ketu',9,'hi','केतु की महादशा में केतु लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',10,'hi','केतु की महादशा में केतु लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',11,'hi','केतु की महादशा में केतु लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('maha','Ketu',12,'hi','केतु की महादशा में केतु लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Venus',1,'hi','शुक्र की महादशा में शुक्र लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',2,'hi','शुक्र की महादशा में शुक्र लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',3,'hi','शुक्र की महादशा में शुक्र लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',4,'hi','शुक्र की महादशा में शुक्र लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',5,'hi','शुक्र की महादशा में शुक्र लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',6,'hi','शुक्र की महादशा में शुक्र लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Venus',7,'hi','शुक्र की महादशा में शुक्र लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',8,'hi','शुक्र की महादशा में शुक्र लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('maha','Venus',9,'hi','शुक्र की महादशा में शुक्र लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',10,'hi','शुक्र की महादशा में शुक्र लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',11,'hi','शुक्र की महादशा में शुक्र लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('maha','Venus',12,'hi','शुक्र की महादशा में शुक्र लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।')
INSERT INTO dasha_lord_from_lagna (context,planet,house_from_lagna,language,positive_text,negative_text,remedy_text) VALUES
('antar','Sun',1,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',2,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',3,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',4,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',5,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',6,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Sun',7,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',8,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Sun',9,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',10,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',11,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें।'),
('antar','Sun',12,'hi','सूर्य की अंतर्दशा में सूर्य लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा आत्मा, पिता, राज्य-पक्ष और यश से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा अहंकार, ताप-विकार और पिता-पक्ष की चिंता संभव है।','सूर्य को जल का अर्घ्य, आदित्यहृदय स्तोत्र का पाठ और रविवार को गुड़-गेहूँ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Moon',1,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',2,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',3,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',4,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',5,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',6,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Moon',7,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',8,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Moon',9,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',10,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',11,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें।'),
('antar','Moon',12,'hi','चन्द्रमा की अंतर्दशा में चन्द्रमा लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा मन, माता, जनप्रियता और सुख से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा मानसिक अशांति, माता को कष्ट और चंचलता संभव है।','सोमवार को शिव उपासना, चावल-दूध-मिश्री का दान और चन्द्र मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Mars',1,'hi','मंगल की अंतर्दशा में मंगल लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',2,'hi','मंगल की अंतर्दशा में मंगल लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',3,'hi','मंगल की अंतर्दशा में मंगल लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',4,'hi','मंगल की अंतर्दशा में मंगल लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',5,'hi','मंगल की अंतर्दशा में मंगल लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',6,'hi','मंगल की अंतर्दशा में मंगल लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Mars',7,'hi','मंगल की अंतर्दशा में मंगल लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',8,'hi','मंगल की अंतर्दशा में मंगल लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Mars',9,'hi','मंगल की अंतर्दशा में मंगल लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',10,'hi','मंगल की अंतर्दशा में मंगल लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',11,'hi','मंगल की अंतर्दशा में मंगल लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें।'),
('antar','Mars',12,'hi','मंगल की अंतर्दशा में मंगल लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा पराक्रम, भूमि-संपत्ति और ऊर्जा से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा क्रोध, विवाद, चोट और रक्त-विकार संभव है।','मंगलवार को हनुमान चालीसा का पाठ तथा मसूर व गुड़ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Rahu',1,'hi','राहु की अंतर्दशा में राहु लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',2,'hi','राहु की अंतर्दशा में राहु लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',3,'hi','राहु की अंतर्दशा में राहु लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',4,'hi','राहु की अंतर्दशा में राहु लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',5,'hi','राहु की अंतर्दशा में राहु लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',6,'hi','राहु की अंतर्दशा में राहु लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Rahu',7,'hi','राहु की अंतर्दशा में राहु लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',8,'hi','राहु की अंतर्दशा में राहु लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Rahu',9,'hi','राहु की अंतर्दशा में राहु लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',10,'hi','राहु की अंतर्दशा में राहु लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',11,'hi','राहु की अंतर्दशा में राहु लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें।'),
('antar','Rahu',12,'hi','राहु की अंतर्दशा में राहु लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा विदेश, अचानक लाभ और आधुनिक क्षेत्र से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा भ्रम, छल, अचानक हानि और बदनामी का भय संभव है।','दुर्गा सप्तशती का पाठ, बुधवार को नारियल जल में प्रवाहित करें और जौ का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Jupiter',1,'hi','गुरु की अंतर्दशा में गुरु लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',2,'hi','गुरु की अंतर्दशा में गुरु लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',3,'hi','गुरु की अंतर्दशा में गुरु लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',4,'hi','गुरु की अंतर्दशा में गुरु लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',5,'hi','गुरु की अंतर्दशा में गुरु लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',6,'hi','गुरु की अंतर्दशा में गुरु लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Jupiter',7,'hi','गुरु की अंतर्दशा में गुरु लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',8,'hi','गुरु की अंतर्दशा में गुरु लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Jupiter',9,'hi','गुरु की अंतर्दशा में गुरु लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',10,'hi','गुरु की अंतर्दशा में गुरु लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',11,'hi','गुरु की अंतर्दशा में गुरु लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें।'),
('antar','Jupiter',12,'hi','गुरु की अंतर्दशा में गुरु लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा ज्ञान, धन, संतान और धर्म से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा संतान-चिंता और धार्मिक कार्यों में बाधा संभव है।','गुरुवार को व्रत, पीली वस्तु/चने की दाल का दान और गुरु-ब्राह्मण की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Saturn',1,'hi','शनि की अंतर्दशा में शनि लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',2,'hi','शनि की अंतर्दशा में शनि लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',3,'hi','शनि की अंतर्दशा में शनि लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',4,'hi','शनि की अंतर्दशा में शनि लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',5,'hi','शनि की अंतर्दशा में शनि लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',6,'hi','शनि की अंतर्दशा में शनि लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Saturn',7,'hi','शनि की अंतर्दशा में शनि लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',8,'hi','शनि की अंतर्दशा में शनि लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Saturn',9,'hi','शनि की अंतर्दशा में शनि लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',10,'hi','शनि की अंतर्दशा में शनि लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',11,'hi','शनि की अंतर्दशा में शनि लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें।'),
('antar','Saturn',12,'hi','शनि की अंतर्दशा में शनि लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा कर्म, सेवा, धैर्य और न्याय से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा विलंब, अधिक श्रम, वात-रोग और सेवक-वर्ग से कष्ट संभव है।','शनिवार को तिल-तेल-लोहे का दान, हनुमान उपासना और असहायों की सेवा करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Mercury',1,'hi','बुध की अंतर्दशा में बुध लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',2,'hi','बुध की अंतर्दशा में बुध लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',3,'hi','बुध की अंतर्दशा में बुध लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',4,'hi','बुध की अंतर्दशा में बुध लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',5,'hi','बुध की अंतर्दशा में बुध लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',6,'hi','बुध की अंतर्दशा में बुध लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Mercury',7,'hi','बुध की अंतर्दशा में बुध लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',8,'hi','बुध की अंतर्दशा में बुध लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Mercury',9,'hi','बुध की अंतर्दशा में बुध लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',10,'hi','बुध की अंतर्दशा में बुध लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',11,'hi','बुध की अंतर्दशा में बुध लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें।'),
('antar','Mercury',12,'hi','बुध की अंतर्दशा में बुध लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा बुद्धि, वाणी, व्यापार और विद्या से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा वाणी-दोष, त्वचा-विकार और व्यापार में उलझन संभव है।','बुधवार को विष्णु सहस्रनाम का पाठ, हरी मूँग और हरे कपड़े का दान करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Ketu',1,'hi','केतु की अंतर्दशा में केतु लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',2,'hi','केतु की अंतर्दशा में केतु लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',3,'hi','केतु की अंतर्दशा में केतु लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',4,'hi','केतु की अंतर्दशा में केतु लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',5,'hi','केतु की अंतर्दशा में केतु लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',6,'hi','केतु की अंतर्दशा में केतु लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Ketu',7,'hi','केतु की अंतर्दशा में केतु लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',8,'hi','केतु की अंतर्दशा में केतु लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Ketu',9,'hi','केतु की अंतर्दशा में केतु लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',10,'hi','केतु की अंतर्दशा में केतु लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',11,'hi','केतु की अंतर्दशा में केतु लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें।'),
('antar','Ketu',12,'hi','केतु की अंतर्दशा में केतु लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा मोक्ष, गूढ़ ज्ञान और वैराग्य से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा अकारण भय, चोट-चिंता और अलगाव की प्रवृत्ति संभव है।','गणेश उपासना, कंबल व तिल का दान और केतु मंत्र का जप करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Venus',1,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 1वें भाव (लग्न भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर शरीर, स्वास्थ्य, व्यक्तित्व और आत्मविश्वास के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर स्वास्थ्य और आत्मविश्वास में कमी तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',2,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 2वें भाव (धन भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर धन-संचय, कुटुंब और वाणी के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। धन भाव से कुटुंब का सहयोग एवं संचित धन की वृद्धि होती है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर धन-संचय व कुटुंब में तनाव और वाणी-दोष तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',3,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 3वें भाव (पराक्रम भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर साहस, भाई-बहन और छोटी यात्राएँ के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाई-बहनों से मतभेद और प्रयासों में बाधा तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',4,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 4वें भाव (सुख भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर माता, भवन, वाहन और मानसिक शांति के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर माता के स्वास्थ्य व भवन-वाहन संबंधी चिंता और मानसिक अशांति तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',5,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 5वें भाव (संतान भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर संतान, विद्या, बुद्धि और पूर्व-पुण्य के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर संतान व विद्या संबंधी चिंता और निर्णय में भूल तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',6,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 6वें भाव (रोग भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर रोग, ऋण, शत्रु और प्रतियोगिता के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर रोग, ऋण और शत्रु-पक्ष से परेशानी तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Venus',7,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 7वें भाव (विवाह भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर विवाह, जीवनसाथी और साझेदारी के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर वैवाहिक जीवन व साझेदारी में तनाव तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',8,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 8वें भाव (आयु भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर आयु, गूढ़ विद्या और आकस्मिक घटनाएँ के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आकस्मिक बाधाएँ, बदनामी और स्वास्थ्य-संकट तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।'),
('antar','Venus',9,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 9वें भाव (भाग्य भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर भाग्य, धर्म, गुरु और पिता के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। त्रिकोण-स्थित होने से भाग्य का सहयोग और पुण्योदय होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर भाग्य में रुकावट तथा पिता या गुरु-पक्ष को कष्ट तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',10,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 10वें भाव (कर्म भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर कर्म, पद-प्रतिष्ठा और राज्य के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। केन्द्र-स्थित होने से दशा के फल स्थिर और प्रत्यक्ष रूप से मिलते हैं।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर कार्यक्षेत्र में बाधा और पद-हानि का भय तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',11,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 11वें भाव (लाभ भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर लाभ, आय और इच्छापूर्ति के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। उपचय भाव में समय के साथ फल बढ़ते जाते हैं; परिश्रम से लाभ निश्चित होता है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर आय में कमी और मित्र-वर्ग से निराशा तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें।'),
('antar','Venus',12,'hi','शुक्र की अंतर्दशा में शुक्र लग्न से 12वें भाव (व्यय भाव) में स्थित है। बलवान, उच्च, अपनी राशि का, मित्र की राशि का या शुभ-दृष्ट होने पर व्यय, विदेश, शय्यासुख और मोक्ष के क्षेत्र में उन्नति होती है तथा सुख, विवाह, वैभव और कला से संबंधित शुभ फल प्राप्त होते हैं। अशुभ भाव में शुभ फल तभी मिलते हैं जब ग्रह बलवान हो; विपरीत राजयोग बनने पर अचानक बड़ा लाभ भी संभव है।','निर्बल, नीच राशि का, अस्त, शत्रु की राशि का या पाप-प्रभाव (पाप-युति/पाप-दृष्टि) में होने पर व्यय की अधिकता, निद्रा-दोष और विदेश संबंधी उलझन तथा भोग-विलास में अधिक व्यय और वैवाहिक तनाव संभव है।','शुक्रवार को सफेद वस्तु (चावल, खीर, कपड़े) का दान और लक्ष्मी उपासना करें। अशुभ भाव में स्थित होने से महामृत्युंजय मंत्र का जप विशेष लाभकारी है।')
INSERT INTO dasha_antar_from_maha (antar_planet,house_from_maha_lord,language,verdict,positive_text,negative_text,remedy_text) VALUES
('ANY',1,'hi','शुभ-मिश्रित','अंतर्दशा स्वामी महादशा स्वामी के साथ या उसी भाव में है — दोनों दशाओं में तालमेल रहता है और महादशा का कार्यक्रम तीव्र होकर फल देता है।','दोनों ग्रहों में परस्पर शत्रुता या पाप-प्रभाव होने पर फल में विरोधाभास और अस्थिरता आती है।','दोनों दशा-स्वामियों के मंत्रों का जप कर सामंजस्य बढ़ाएँ।'),
('ANY',2,'hi','शुभ','महादशेश से द्वितीय — धन-संचय, कुटुंब का सहयोग और वाणी से लाभ मिलता है।','पाप-प्रभाव में पारिवारिक व आर्थिक तनाव।','अन्नदान करें और वाणी में संयम रखें।'),
('ANY',3,'hi','मिश्रित','महादशेश से तृतीय — प्रारंभिक संघर्ष के बाद पराक्रम से उपलब्धि; यात्राओं से लाभ।','आरंभ में प्रयास अधिक, फल कम; भाई-पक्ष से मतभेद।','हनुमान उपासना से पराक्रम-वृद्धि करें।'),
('ANY',4,'hi','शुभ','महादशेश से चतुर्थ (केन्द्र) — सुख-शांति, भवन-वाहन और माता-पक्ष से शुभ फल।','पीड़ित होने पर मानसिक अशांति।','सोमवार को दूध का दान करें।'),
('ANY',5,'hi','शुभ','महादशेश से पंचम (त्रिकोण) — संतान, विद्या और मंत्रणा से शुभ फल; पूर्व-पुण्य का उदय।','पीड़ित होने पर संतान-चिंता।','इष्ट देवता का जप बढ़ाएँ।'),
('ANY',6,'hi','अशुभ','','महादशेश से षष्ठ — दोनों दशाओं में परस्पर संघर्ष (षडाष्टक दोष); रोग, ऋण, विवाद और शत्रु-वृद्धि का समय।','महामृत्युंजय जप, औषधि-दान और शत्रुता से बचाव करें।'),
('ANY',7,'hi','शुभ','महादशेश से सप्तम (केन्द्र) — साझेदारी, विवाह-पक्ष और जनसंपर्क से लाभ; दोनों ग्रह आमने-सामने संतुलित बल में।','ग्रहों में शत्रुता होने पर साझेदारी में खिंचाव।','सफेद वस्तु का दान करें।'),
('ANY',8,'hi','अशुभ','','महादशेश से अष्टम — बाधा, अचानक उतार-चढ़ाव, बदनामी और स्वास्थ्य-संकट की आशंका (षडाष्टक दोष)।','महामृत्युंजय मंत्र का जप और तिल-दान करें।'),
('ANY',9,'hi','अति शुभ','महादशेश से नवम (त्रिकोण) — भाग्य का पूर्ण सहयोग; धर्म-कार्य, गुरु-कृपा और उन्नति का श्रेष्ठ समय।','पीड़ित होने पर भाग्य में विलंब मात्र।','गुरुवार को धर्म-कार्य व दान करें।'),
('ANY',10,'hi','शुभ','महादशेश से दशम (केन्द्र) — कर्म-सफलता, पद-प्रतिष्ठा और राज्य-पक्ष से लाभ।','पीड़ित होने पर कार्य-भार अधिक।','कर्मस्थान पर सेवा-भाव रखें।'),
('ANY',11,'hi','शुभ','महादशेश से एकादश — आय-वृद्धि, इच्छापूर्ति और मित्र-वर्ग से लाभ।','पाप-प्रभाव में लोभ से हानि।','आय का अंश दान करें।'),
('ANY',12,'hi','अशुभ','','महादशेश से द्वादश — व्यय की अधिकता, शक्ति-क्षय और महादशा के फल क्षीण होते हैं (द्विर्द्वादश दोष)।','व्यय पर नियंत्रण रखें; शय्या-दान व दीप-दान करें।')
INSERT INTO house_engine_config (cfg_key,cfg_value,notes) VALUES
('dasha_engine_show_remedy_always','0','1 = हर कार्ड में उपाय दिखाएँ; 0 = केवल मिश्रित/अशुभ पर')
